import{_ as l,l as i,o as e,c as n,v as o,p as s,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"名字解析","description":"","frontmatter":{"title":"名字解析","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/name-resolution.md","filePath":"cs/name-resolution.md","lastUpdated":1789023840000}'),h={name:"cs/name-resolution.md"};function m(_,a,u,A,E,f){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="名字解析" tabindex="-1">名字解析 <a class="header-anchor" href="#名字解析" aria-label="Permalink to &quot;名字解析&quot;">​</a></h1><div class="epigraph"><p>查找把每个使用点绑到唯一声明（或报未声明、不明确）；此后遍比较的是声明记录，不再比字符串。</p><footer>—— 据龙书第 6 章；Appel, Modern Compiler Implementation 整理</footer></div><p>上一课<a href="/cs/scope-symtab">作用域与符号表</a>给出层叠映射与遮蔽，并声明使用处从内向外查。本课不重做 push/pop。缺口是<strong>解析本身</strong>：把查找结果写回 AST、处理前向引用、限定名与导入路径、以及失败种类（未声明、在声明前使用、二义导入）。类型是否匹配下一课才查；本课可以绑到「还只有占位类型」的记录。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>符号表是结构；解析是遍：遇声明插入，遇使用查找，节点上挂 <code>decl</code> 指针。块结构语言一遍即可。类成员、方法与字段的前向引用要两遍：先收声明，再解析使用。C 的原型与定义、Java 的类体都属于「先建完当前层再查」。缺口是这份次序，不是再解释散列。</p><p>限定名 <code>M.x</code>：先解析 <code>M</code> 到模块或对象，再在那一层查 <code>x</code>。导入把外层名字拷进当前查找路径；冲突要报不明确，不能静默挑一个。</p><h3 id="绑定不是链接" tabindex="-1">绑定不是链接 <a class="header-anchor" href="#绑定不是链接" aria-label="Permalink to &quot;绑定不是链接&quot;">​</a></h3><p>编译单元内的解析结束于本文件能看见的声明。别的 <code>.o</code> 里的 <code>printf</code> 仍是未定义符号，留给<a href="/cs/link-reloc">链接</a>。本课失败叫「未声明」；链接失败叫「未定义引用」。不要混。</p><p><span class="marginnote">龙书把符号表查找写成语义分析的一部分。Appel 强调 AST 上替换名字为标签。重载要等类型信息，下一课与再下一课；本课默认同层同名冲突，除非语言规定函数可同名待选。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按语言选一遍或两遍访问者。插入时查当前层冲突。查找失败：诊断 + 可插入错误声明以免级联。写回绑定后，后续遍禁止再用标识符拼写当键（宏除外）。</p>',11)),(e(),s(p,null,{default:t(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ID%5B%22%E4%BD%BF%E7%94%A8%E7%82%B9%20id%22%5D%20--%3E%20LOOK%5B%22%E5%B1%82%E5%8F%A0%E6%9F%A5%E6%89%BE%22%5D%0A%20%20LOOK%20--%3E%20BIND%5B%22AST%20%E6%8C%82%E5%A3%B0%E6%98%8E%22%5D%0A%20%20LOOK%20--%3E%20ERR%5B%22%E6%9C%AA%E5%A3%B0%E6%98%8E%20%2F%20%E4%BA%8C%E4%B9%89%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>静态链、捕获变量：解析时标记「来自外层函数」，闭包实现后置；本课只记绑定深度。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了指针，改名重构与报错下划线都能指向声明处。<a href="/cs/calling-convention-stack">调用约定</a> 的槽位尚未分配，记录里的偏移仍空。同名类型与同名变量分属不同名字空间时，查找要带种类——C 的 <code>struct</code> 标签即例，点名。</p><p>动态作用域不在主干：运行时沿调用链查，编译期绑不紧。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不检查类型、不做隐式转换、不决议重载。不处理链接期弱符号。后课默认：每个合法使用点有唯一定义指针。类型综合与比对是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>解析 = 查找 + 写回绑定；前向引用可能要两遍。</li><li>未声明是前端诊断；未定义引用是链接诊断。</li><li>重载与类型下一课才进查找键。</li><li>出处：Aho et al., 龙书第 6 章；Appel。</li></ul>',8))])}const b=l(h,[["render",m]]);export{B as __pageData,b as default};
